import React from "react";
import "./App.css";

function Navbar() {
  return (
    <nav className="navbar">
      <h2>Nisha.dev</h2>

      <ul>
        <li><a href="#home">Home</a></li>
        <li><a href="#about">About</a></li>
        <li><a href="#projects">Projects</a></li>
        <li><a href="#contact">Contact</a></li>
      </ul>
    </nav>
  );
}

export default Navbar;
